using System;
using System.Buffers.Binary;
using System.Security.Cryptography;

namespace Titanium.Tls;

/// <summary>
/// SHA-3 and SHAKE. The platform implementation is used when it exists. Otherwise the permutation
/// is the Keccak-f[1600] function from FIPS 202, including the round constants generated by its LFSR.
/// </summary>
internal interface IKeccak
{
    void Sha3_256(ReadOnlySpan<byte> input, Span<byte> output);

    void Sha3_512(ReadOnlySpan<byte> input, Span<byte> output);

    void Shake128(ReadOnlySpan<byte> input, Span<byte> output);

    void Shake256(ReadOnlySpan<byte> input, Span<byte> output);
}

internal static class Keccak
{
    internal static IKeccak Create(bool forceManaged = false)
    {
        if (!forceManaged && SHA3_256.IsSupported && SHA3_512.IsSupported && Shake128.IsSupported && Shake256.IsSupported)
        {
            return BclKeccak.Instance;
        }

        return ManagedKeccak.Instance;
    }
}

internal sealed class BclKeccak : IKeccak
{
    internal static readonly BclKeccak Instance = new();

    public void Sha3_256(ReadOnlySpan<byte> input, Span<byte> output)
    {
        SHA3_256.HashData(input, output);
    }

    public void Sha3_512(ReadOnlySpan<byte> input, Span<byte> output)
    {
        SHA3_512.HashData(input, output);
    }

    public void Shake128(ReadOnlySpan<byte> input, Span<byte> output)
    {
        System.Security.Cryptography.Shake128.HashData(input, output);
    }

    public void Shake256(ReadOnlySpan<byte> input, Span<byte> output)
    {
        System.Security.Cryptography.Shake256.HashData(input, output);
    }
}

internal sealed class ManagedKeccak : IKeccak
{
    internal static readonly ManagedKeccak Instance = new();

    private const int LaneCount = 25;

    private static readonly ulong[] RoundConstants = BuildRoundConstants();

    public void Sha3_256(ReadOnlySpan<byte> input, Span<byte> output)
    {
        if (output.Length != 32)
        {
            throw new ArgumentException("SHA3-256 writes 32 bytes.");
        }

        Sponge(input, output, rate: 136, domain: 0x06);
    }

    public void Sha3_512(ReadOnlySpan<byte> input, Span<byte> output)
    {
        if (output.Length != 64)
        {
            throw new ArgumentException("SHA3-512 writes 64 bytes.");
        }

        Sponge(input, output, rate: 72, domain: 0x06);
    }

    public void Shake128(ReadOnlySpan<byte> input, Span<byte> output)
    {
        Sponge(input, output, rate: 168, domain: 0x1F);
    }

    public void Shake256(ReadOnlySpan<byte> input, Span<byte> output)
    {
        Sponge(input, output, rate: 136, domain: 0x1F);
    }

    private static void Sponge(ReadOnlySpan<byte> input, Span<byte> output, int rate, byte domain)
    {
        Span<ulong> state = stackalloc ulong[LaneCount];
        int offset = 0;
        while (input.Length - offset >= rate)
        {
            XorLaneBytes(state, input.Slice(offset, rate));
            Permute(state);
            offset += rate;
        }

        Span<byte> tail = stackalloc byte[168];
        input[offset..].CopyTo(tail);
        tail[input.Length - offset] ^= domain;
        tail[rate - 1] ^= 0x80;
        XorLaneBytes(state, tail[..rate]);
        Permute(state);
        int produced = 0;
        while (produced < output.Length)
        {
            int take = Math.Min(rate, output.Length - produced);
            StoreLaneBytes(state, output.Slice(produced, take));
            produced += take;
            if (produced < output.Length)
            {
                Permute(state);
            }
        }
    }

    private static void XorLaneBytes(Span<ulong> state, ReadOnlySpan<byte> block)
    {
        int lane = 0;
        int offset = 0;
        while (offset + 8 <= block.Length)
        {
            state[lane++] ^= BinaryPrimitives.ReadUInt64LittleEndian(block.Slice(offset, 8));
            offset += 8;
        }

        if (offset < block.Length)
        {
            ulong partial = 0;
            for (int i = 0; offset + i < block.Length; i++)
            {
                partial |= (ulong)block[offset + i] << (8 * i);
            }

            state[lane] ^= partial;
        }
    }

    private static void StoreLaneBytes(ReadOnlySpan<ulong> state, Span<byte> destination)
    {
        int lane = 0;
        int offset = 0;
        while (offset + 8 <= destination.Length)
        {
            BinaryPrimitives.WriteUInt64LittleEndian(destination.Slice(offset, 8), state[lane++]);
            offset += 8;
        }

        if (offset < destination.Length)
        {
            ulong value = state[lane];
            for (int i = 0; offset + i < destination.Length; i++)
            {
                destination[offset + i] = (byte)(value >> (8 * i));
            }
        }
    }

    private static void Permute(Span<ulong> a)
    {
        Span<ulong> b = stackalloc ulong[LaneCount];
        Span<ulong> c = stackalloc ulong[5];
        for (int round = 0; round < 24; round++)
        {
            c.Clear();
            for (int x = 0; x < 5; x++)
            {
                c[x] = a[x] ^ a[x + 5] ^ a[x + 10] ^ a[x + 15] ^ a[x + 20];
            }

            for (int x = 0; x < 5; x++)
            {
                ulong d = c[(x + 4) % 5] ^ RotateLeft(c[(x + 1) % 5], 1);
                for (int y = 0; y < 5; y++)
                {
                    a[x + (5 * y)] ^= d;
                }
            }

            b.Clear();
            b[0] = a[0];
            int px = 1;
            int py = 0;
            for (int t = 0; t < 24; t++)
            {
                int rotation = ((t + 1) * (t + 2) / 2) % 64;
                int nx = py;
                int ny = ((2 * px) + (3 * py)) % 5;
                b[nx + (5 * ny)] = RotateLeft(a[px + (5 * py)], rotation);
                px = nx;
                py = ny;
            }

            for (int y = 0; y < 5; y++)
            {
                for (int x = 0; x < 5; x++)
                {
                    a[x + (5 * y)] = b[x + (5 * y)] ^ ((~b[((x + 1) % 5) + (5 * y)]) & b[((x + 2) % 5) + (5 * y)]);
                }
            }

            a[0] ^= RoundConstants[round];
        }
    }

    private static ulong RotateLeft(ulong value, int bits)
    {
        if (bits == 0)
        {
            return value;
        }

        return (value << bits) | (value >> (64 - bits));
    }

    private static ulong[] BuildRoundConstants()
    {
        ulong[] constants = new ulong[24];
        for (int round = 0; round < 24; round++)
        {
            ulong lane = 0;
            for (int j = 0; j < 7; j++)
            {
                int bit = Rc((j + (7 * round)) % 255);
                lane |= (ulong)bit << ((1 << j) - 1);
            }

            constants[round] = lane;
        }

        return constants;
    }

    private static int Rc(int t)
    {
        if (t == 0)
        {
            return 1;
        }

        Span<int> r = stackalloc int[8];
        Span<int> next = stackalloc int[9];
        r[0] = 1;
        for (int i = 1; i <= t; i++)
        {
            next.Clear();
            for (int bit = 0; bit < 8; bit++)
            {
                next[bit + 1] = r[bit];
            }

            next[0] ^= next[8];
            next[4] ^= next[8];
            next[5] ^= next[8];
            next[6] ^= next[8];
            for (int bit = 0; bit < 8; bit++)
            {
                r[bit] = next[bit];
            }
        }

        return r[0];
    }
}
